// Counting and probability helpers, each formula checked against brute force
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

public class CombinatoricsProbability {
    static long factorial(int n) {
        long ans = 1;
        for (int i = 2; i <= n; i++) ans *= i;
        return ans;
    }

    static long permutations(int n, int k) {
        long ans = 1;
        for (int i = 0; i < k; i++) ans *= n - i; // n * (n-1) * ... * (n-k+1) = n!/(n-k)!
        return ans;
    }

    // Multiplicative formula: each partial result is itself a binomial coefficient, so the division is exact
    static long nCr(int n, int r) {
        long ans = 1;
        for (int i = 1; i <= r; i++) ans = ans * (n - r + i) / i;
        return ans;
    }

    public static void main(String[] args) {
        int n = 5, r = 2;
        System.out.println("5! = " + factorial(5));
        System.out.println("P(5,2) = 5!/3! = " + permutations(n, r));
        System.out.println("C(5,2) = " + nCr(n, r));

        int subsets = 0; // brute force: count 5-bit masks with exactly two 1-bits
        for (int mask = 0; mask < (1 << n); mask++) {
            if (Integer.bitCount(mask) == r) subsets++;
        }
        System.out.println("brute force: " + subsets + " two-element subsets of {1..5}");
        System.out.println("order matters: P(5,2) = C(5,2) * 2! = " + nCr(n, r) + " * " + factorial(r) + " = "
                + nCr(n, r) * factorial(r));

        List<String> twoHeads = new ArrayList<>();
        for (int i = 0; i < 8; i++) {
            StringBuilder s = new StringBuilder();
            for (int bit = 2; bit >= 0; bit--) s.append((i >> bit & 1) == 1 ? 'H' : 'T');
            if (Integer.bitCount(i) == 2) twoHeads.add(s.toString());
        }
        System.out.println("exactly 2 heads among the 8 outcomes of 3 flips: " + String.join(" ", twoHeads));
        System.out.println("P(exactly 2 heads in 3 fair flips) = " + twoHeads.size() + "/8 = "
                + String.format(Locale.ROOT, "%.4f", twoHeads.size() / 8.0));
        System.out.println("binomial formula: C(3,2) * (1/2)^2 * (1/2)^1 = " + nCr(3, 2) + "/8");
    }
}

