    const int n = 5, r = 2;
    std::printf("5! = %lld\n", factorial(5));
    std::printf("P(5,2) = 5!/3! = %lld\n", permutations(n, r));
    std::printf("C(5,2) = %lld\n", nCr(n, r));

    int subsets = 0;  // brute force: count 5-bit masks with exactly two 1-bits
    for (int mask = 0; mask < (1 << n); mask++) {
        if (std::bitset<n>(mask).count() == r) subsets++;
