    std::printf("brute force: %d two-element subsets of {1..5}\n", subsets);
    std::printf("order matters: P(5,2) = C(5,2) * 2! = %lld * %lld = %lld\n", nCr(n, r), factorial(r),
                nCr(n, r) * factorial(r));

    std::string twoHeads;
    int favorable = 0;
    for (int i = 0; i < 8; i++) {
        std::string s;
        for (int bit = 2; bit >= 0; bit--) s += ((i >> bit) & 1) ? 'H' : 'T';
        if (std::bitset<3>(i).count() == 2) {
            twoHeads += (favorable ? " " : "") + s;
            favorable++;
        }
    }
    std::printf("exactly 2 heads among the 8 outcomes of 3 flips: %s\n", twoHeads.c_str());
    std::printf("P(exactly 2 heads in 3 fair flips) = %d/8 = %.4f\n", favorable, favorable / 8.0);
    std::printf("binomial formula: C(3,2) * (1/2)^2 * (1/2)^1 = %lld/8\n", nCr(3, 2));
}

