import java.math.BigInteger;

// n! grows so fast that 21! no longer fits in a 64-bit long
public class FactorialOverflow {
    static long factorial(int n) {
        long ans = 1; // 0! = 1: there is exactly one way to arrange nothing
        for (int i = 2; i <= n; i++) ans *= i;
        return ans;
    }

    public static void main(String[] args) {
        for (int n : new int[] {0, 1, 2, 3, 4, 5, 10, 15, 20}) {
            System.out.printf("%2d! = %d%n", n, factorial(n));
        }
        System.out.println("recursive rule: 20! == 20 * 19! -> " + (factorial(20) == 20 * factorial(19)));

        // Find the largest n with n! <= Long.MAX_VALUE without ever overflowing
        long f = 1;
        int n = 0;
        while (f <= Long.MAX_VALUE / (n + 1)) {
            n++;
            f *= n;
        }
        System.out.println("largest n with n! <= 2^63-1: " + n);

        BigInteger exact = BigInteger.valueOf(factorial(20)).multiply(BigInteger.valueOf(21));
        long wrapped = factorial(20) * 21; // Java long arithmetic wraps around silently
        System.out.println("21! exactly          = " + exact);
        System.out.println("long max (2^63-1)    = " + Long.MAX_VALUE);
        System.out.println("21! in a 64-bit long = " + wrapped + " (overflowed, no error raised)");
    }
}

