#include <string>
#include <vector>

const int N = 60;

long long nCr(int n, int k) {
    long long ans = 1;
    for (int i = 1; i <= k; i++) ans = ans * (n - k + i) / i;  // stays below 2^63 for n <= 60
    return ans;
}

int main() {
    std::vector<std::vector<long long>> c(N + 1, std::vector<long long>(N + 1, 0));
    for (int n = 0; n <= N; n++) {
        c[n][0] = c[n][n] = 1;  // one way to choose nothing, one way to choose everything
        for (int k = 1; k < n; k++) c[n][k] = c[n - 1][k - 1] + c[n - 1][k];
    }
    for (int n = 0; n <= 6; n++) {
        std::string row;
        long long sum = 0;
        for (int k = 0; k <= n; k++) {
            row += (k ? " " : "") + std::to_string(c[n][k]);
            sum += c[n][k];
        }
        // Row n sums to 2^n: each subset of an n-set has some size k
        std::printf("row %d: %-18s sum = %lld = 2^%d\n", n, row.c_str(), sum, n);
    }
    std::printf("Pascal's rule: C(6,2) = C(5,1) + C(5,2) = %lld + %lld = %lld\n", c[5][1], c[5][2], c[6][2]);
    std::printf("symmetry: C(6,2) = C(6,4) = %lld\n", c[6][4]);
    std::printf("C(30,15): Pascal table %lld, multiplicative %lld\n", c[30][15], nCr(30, 15));
    std::printf("C(60,30): Pascal table %lld, multiplicative %lld\n", c[60][30], nCr(60, 30));
    std::printf("(60! itself has 82 digits, so n!/(k!(n-k)!) cannot work in 64 bits)\n");
}

