import java.util.Locale;
import java.util.function.BiPredicate;

// Probability in a uniform sample space: P(E) = |E| / |S|, kept as exact fractions
public class DiceEventProbability {
    record Frac(long num, long den) {
        static long gcd(long a, long b) {
            return b == 0 ? Math.abs(a) : gcd(b, a % b);
        }

        static Frac of(long num, long den) {
            long g = gcd(num, den);
            return new Frac(num / g, den / g); // always store in lowest terms
        }

        Frac plus(Frac o) { return of(num * o.den + o.num * den, den * o.den); }
        Frac minus(Frac o) { return of(num * o.den - o.num * den, den * o.den); }
        Frac times(Frac o) { return of(num * o.num, den * o.den); }

        @Override
        public String toString() { return num + "/" + den; }
    }

    // "6/36 = 1/6 = 0.1667": the raw count, the reduced fraction, then a decimal
    static String describe(long count, long total) {
        Frac f = Frac.of(count, total);
        String raw = count + "/" + total;
        String reduced = f.toString().equals(raw) ? "" : " = " + f;
        return raw + reduced + " = " + String.format(Locale.ROOT, "%.4f", (double) count / total);
    }

    static long count(BiPredicate<Integer, Integer> event) {
        long c = 0;
        for (int a = 1; a <= 6; a++) for (int b = 1; b <= 6; b++) if (event.test(a, b)) c++;
        return c;
    }

    public static void main(String[] args) {
        System.out.println("sample space: 6 * 6 = 36 equally likely (die1, die2) outcomes");
        long sum7 = count((a, b) -> a + b == 7);
        long six = count((a, b) -> a == 6 || b == 6);
        long noSix = count((a, b) -> a != 6 && b != 6);
        long even = count((a, b) -> a % 2 == 0);
        long both = count((a, b) -> a % 2 == 0 && a + b == 7);
        long either = count((a, b) -> a % 2 == 0 || a + b == 7);
        System.out.println("P(sum = 7)          = " + describe(sum7, 36));
        System.out.println("P(at least one six) = " + describe(six, 36));
        System.out.println("  complement check: 1 - P(no six) = 1 - " + Frac.of(noSix, 36) + " = "
                + Frac.of(1, 1).minus(Frac.of(noSix, 36)));
        System.out.println("P(A: die1 even)     = " + describe(even, 36));
        System.out.println("P(A and sum 7)      = " + describe(both, 36));
        Frac pA = Frac.of(even, 36), pB = Frac.of(sum7, 36), pAB = Frac.of(both, 36);
        System.out.println("P(A or sum 7)       = " + describe(either, 36) + ", formula " + pA + " + " + pB
                + " - " + pAB + " = " + pA.plus(pB).minus(pAB));
        System.out.println("independent? P(A)P(B) = " + pA.times(pB) + ", P(A and B) = " + pAB + " -> "
                + (pA.times(pB).equals(pAB) ? "yes" : "no"));

        // "At least one" is easiest through the complement: 1 - P(no six in 4 rolls)
        long hits = 0;
        for (int code = 0; code < 1296; code++) {
            boolean sawSix = false;
            for (int c = code, roll = 0; roll < 4; roll++, c /= 6) sawSix |= c % 6 == 5;
            if (sawSix) hits++;
        }
        Frac fiveSixths = Frac.of(5, 6);
        Frac none = fiveSixths.times(fiveSixths).times(fiveSixths).times(fiveSixths);
        System.out.println("P(a six in 4 rolls) = 1 - (5/6)^4 = " + Frac.of(1, 1).minus(none)
                + "; brute force: " + describe(hits, 1296));
    }
}

