#include <cstdio>
#include <functional>
#include <iostream>
#include <numeric>
#include <string>

struct Frac {
    long long num, den;

    // Always store in lowest terms
    static Frac of(long long num, long long den) {
        long long g = std::gcd(num, den);
        return {num / g, den / g};
    }
    Frac operator+(const Frac& o) const { return of(num * o.den + o.num * den, den * o.den); }
    Frac operator-(const Frac& o) const { return of(num * o.den - o.num * den, den * o.den); }
    Frac operator*(const Frac& o) const { return of(num * o.num, den * o.den); }
    bool operator==(const Frac& o) const { return num == o.num && den == o.den; }
    std::string str() const { return std::to_string(num) + "/" + std::to_string(den); }
};

// "6/36 = 1/6 = 0.1667": the raw count, the reduced fraction, then a decimal
std::string describe(long long count, long long total) {
    std::string raw = std::to_string(count) + "/" + std::to_string(total);
    std::string reduced = Frac::of(count, total).str();
    char dec[32];
    std::snprintf(dec, sizeof dec, "%.4f", static_cast<double>(count) / total);
    return raw + (reduced == raw ? "" : " = " + reduced) + " = " + dec;
}

long long count(const std::function<bool(int, int)>& event) {
    long long c = 0;
    for (int a = 1; a <= 6; a++)
        for (int b = 1; b <= 6; b++)
            if (event(a, b)) c++;
    return c;
}

int main() {
    std::cout << "sample space: 6 * 6 = 36 equally likely (die1, die2) outcomes\n";
    long long sum7 = count([](int a, int b) { return a + b == 7; });
    long long six = count([](int a, int b) { return a == 6 || b == 6; });
    long long noSix = count([](int a, int b) { return a != 6 && b != 6; });
    long long even = count([](int a, int) { return a % 2 == 0; });
    long long both = count([](int a, int b) { return a % 2 == 0 && a + b == 7; });
    long long either = count([](int a, int b) { return a % 2 == 0 || a + b == 7; });
    const Frac one{1, 1};
    std::cout << "P(sum = 7)          = " << describe(sum7, 36) << "\n";
    std::cout << "P(at least one six) = " << describe(six, 36) << "\n";
    std::cout << "  complement check: 1 - P(no six) = 1 - " << Frac::of(noSix, 36).str() << " = "
              << (one - Frac::of(noSix, 36)).str() << "\n";
    std::cout << "P(A: die1 even)     = " << describe(even, 36) << "\n";
    std::cout << "P(A and sum 7)      = " << describe(both, 36) << "\n";
    Frac pA = Frac::of(even, 36), pB = Frac::of(sum7, 36), pAB = Frac::of(both, 36);
    std::cout << "P(A or sum 7)       = " << describe(either, 36) << ", formula " << pA.str() << " + " << pB.str()
              << " - " << pAB.str() << " = " << (pA + pB - pAB).str() << "\n";
    std::cout << "independent? P(A)P(B) = " << (pA * pB).str() << ", P(A and B) = " << pAB.str() << " -> "
              << (pA * pB == pAB ? "yes" : "no") << "\n";

    // "At least one" is easiest through the complement: 1 - P(no six in 4 rolls)
    long long hits = 0;
    for (int code = 0; code < 1296; code++) {
        bool sawSix = false;
        for (int c = code, roll = 0; roll < 4; roll++, c /= 6) sawSix = sawSix || c % 6 == 5;
        if (sawSix) hits++;
    }
    Frac fiveSixths = Frac::of(5, 6);
    Frac none = fiveSixths * fiveSixths * fiveSixths * fiveSixths;
    std::cout << "P(a six in 4 rolls) = 1 - (5/6)^4 = " << (one - none).str()
              << "; brute force: " << describe(hits, 1296) << "\n";
}

